import {
  Group,
  Mesh,
  PlaneGeometry,
  Vector2,
  Vector3,
  Matrix4,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<number>} position [x, y, z]
 * @property {Array<number>} rotation [x, y, z] in radians
 * @property {Array<number>} scale [x, y, z]
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<Object>} cinematicPrimitives
 * @property {Array<Object>} textContent
 * @property {Object} atlasRegion
 * @property {number} atlasRegion.atlas
 * @property {Object} atlasRegion.sourceRect {x,y,width,height}
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string):THREE.Texture} textureLoader
 * @property {Object} primitives
 * @property {Object} fontAtlas { texture: THREE.Texture, width: number, height: number }
 */

/**
 * Creates a UI node for the “Collection 2” label.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Group container
  const container = new Group();

  // Apply transform from config (fallback to defaults)
  const pos = config.position || [0, 0, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  container.position.set(pos[0], pos[1], pos[2]);
  container.rotation.set(rot[0], rot[1], rot[2]);
  container.scale.set(scl[0], scl[1], scl[2]);

  // ---------- Background Plane (brushed metal) ----------
  const bgGeometry = new PlaneGeometry(1, 1);
  const metalTex = ctx.textureLoader(config.assets?.imageUrl);
  const bgMaterial = new MeshBasicNodeMaterial();
  bgMaterial.map = metalTex;
  bgMaterial.transparent = false;
  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  // Align plane to face camera (default plane is XY, we keep it)
  container.add(bgMesh);

  // ---------- Text Plane ----------
  // Expect a single text entry; fallback to placeholder
  const textEntry = (config.textContent && config.textContent[0]) || {
    text: 'Collection 2',
  };
  const atlas = ctx.fontAtlas;
  const rect = (config.atlasRegion && config.atlasRegion.sourceRect) || {
    x: 0,
    y: 0,
    width: atlas.width,
    height: atlas.height,
  };

  const textGeometry = new PlaneGeometry(1, 1);
  const textMaterial = new MeshBasicNodeMaterial();
  textMaterial.map = atlas.texture;
  // UV transform to sample the correct region of the atlas
  textMaterial.map.offset = new Vector2(
    rect.x / atlas.width,
    rect.y / atlas.height
  );
  textMaterial.map.repeat = new Vector2(
    rect.width / atlas.width,
    rect.height / atlas.height
  );
  textMaterial.transparent = true;
  const textMesh = new Mesh(textGeometry, textMaterial);
  // Position the text slightly in front of the background
  textMesh.position.set(0, 0, 0.001);
  container.add(textMesh);

  // ---------- Apply Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(container, prim.params);
      }
    }
  }

  // ---------- UserData (handlers & cleanup) ----------
  const timelines = []; // store GSAP timelines if any are created later

  container.userData.handlers = {};

  container.userData.cleanup = () => {
    // Dispose geometries and materials owned by this node
    bgGeometry.dispose();
    bgMaterial.dispose();
    textGeometry.dispose();
    textMaterial.dispose();

    // Kill any GSAP timelines created for this node
    for (const tl of timelines) {
      tl.kill();
    }
    timelines.length = 0;
  };

  return container;
}
